use std::io::{self,BufRead,Write};
fn main(){let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout().lock());let mut db:Option<engine::Engine>=None;for line in stdin.lock().lines(){let line=match line{Ok(x)=>x,Err(_)=>break};let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||->Result<query::Data,String>{let req:serde_json::Value=serde_json::from_str(&line).map_err(|e|format!("invalid JSON: {}",e))?;match req.get("op").and_then(|v|v.as_str()).unwrap_or(""){"open"=>{db=None;db=Some(engine::Engine::open(req.get("path").and_then(|v|v.as_str()).unwrap_or(":memory:"))?);Ok(query::Data::default())},"close"=>{db=None;Ok(query::Data::default())},"execute"=>{let sql=req.get("sql").and_then(|v|v.as_str()).ok_or("sql must be a string")?;db.as_mut().ok_or("no open database connection")?.execute(sql)},_=>Err("unknown operation".into())}}));let response=match result{Ok(Ok(data))=>serde_json::json!({"ok":true,"columns":data.fields.iter().map(|f|&f.name).collect::<Vec<_>>(),"rows":data.rows.iter().map(|r|r.iter().map(value::V::json).collect::<Vec<_>>()).collect::<Vec<_>>()}),Ok(Err(e))=>serde_json::json!({"ok":false,"error":e}),Err(_)=>serde_json::json!({"ok":false,"error":"internal evaluation error"})};if writeln!(out,"{}",response).is_err(){break}if out.flush().is_err(){break}}}
